class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();                 // insertion order = recency order
  }
  get(key) {
    if (!this.map.has(key)) return -1;
    const v = this.map.get(key);
    this.map.delete(key);                 // remove…
    this.map.set(key, v);                 // …re-insert to mark as most recent
    return v;
  }
  put(key, value) {
    if (this.map.has(key)) {
      this.map.delete(key);               // update bumps recency too
    } else if (this.map.size >= this.capacity) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);            // evict the front (LRU)
    }
    this.map.set(key, value);
  }
}
// Time O(1) per op, Space O(capacity)

